// Package disk: media.FileStore on local disk (MEDIA_DIR).
// ponytail: a single local folder; switch to S3/MinIO if the service runs >1 instance.
package disk

import (
	"io"
	"os"
	"path/filepath"
	"regexp"

	"eam/services/common/errs"
)

type Store struct{ dir string }

func New(dir string) (*Store, error) {
	return &Store{dir}, os.MkdirAll(dir, 0o750)
}

// IDs are generated by the server (rand.Text: A-Z2-7); anything else is rejected so it cannot escape the folder.
var idRe = regexp.MustCompile(`^[A-Za-z0-9]{1,64}$`)

func (s *Store) path(id string) (string, error) {
	if !idRe.MatchString(id) {
		return "", errs.Invalid("file id is invalid")
	}
	return filepath.Join(s.dir, id), nil
}

func (s *Store) Write(id string, r io.Reader) error {
	p, err := s.path(id)
	if err != nil {
		return err
	}
	f, err := os.Create(p)
	if err != nil {
		return err
	}
	if _, err := io.Copy(f, r); err != nil {
		f.Close()
		os.Remove(p)
		return err
	}
	return f.Close()
}

func (s *Store) Open(id string) (io.ReadCloser, error) {
	p, err := s.path(id)
	if err != nil {
		return nil, err
	}
	f, err := os.Open(p)
	if os.IsNotExist(err) {
		return nil, errs.NotFound("file")
	}
	return f, err
}

func (s *Store) Remove(id string) error {
	p, err := s.path(id)
	if err != nil {
		return err
	}
	return os.Remove(p)
}
